class Solution:
    def numberOfRightTriangles(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Count number of 1s in each row
        row_counts = [0] * m
        # Count number of 1s in each column
        col_counts = [0] * n

        # Populate row and column counts
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    row_counts[i] += 1
                    col_counts[j] += 1

        # Count right triangles
        result = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    # If there's at least one other 1 in the same row and one in the same column
                    if row_counts[i] > 1 and col_counts[j] > 1:
                        result += (row_counts[i] - 1) * (col_counts[j] - 1)

        return result

