class Solution:
    def maxSum(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7

        # Count the number of 1-bits at each position
        bit_count = [0] * 31  # 31 bits enough for numbers up to 10^9

        for num in nums:
            for bit in range(31):
                if num & (1 << bit):
                    bit_count[bit] += 1

        # Construct k largest numbers by greedily assigning bits
        numbers = []

        for _ in range(k):
            # Build the current number by assigning available bits from highest to lowest
            current_num = 0
            for bit in range(30, -1, -1):  # from highest bit to lowest
                if bit_count[bit] > 0:
                    # Assign this bit to our number
                    current_num |= (1 << bit)
                    bit_count[bit] -= 1
            numbers.append(current_num)

        # Calculate sum of squares
        result = 0
        for num in numbers:
            result = (result + num * num) % MOD

        return result

